import { readFileSync, writeFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import { projectNutritionMealFacts, readNutritionUnitsResult } from './nutrition-window-service'

// Actual seven RPC observations generated by real SQL writers and reader in
// a controlled rollback transaction. They are pieces, NOT a full HTTP window.
const golden = JSON.parse(
  readFileSync(
    new URL(
      '../../../../ios/BodyFlow/BodyFlowTests/Fixtures/NutritionWindowUnitsSQLPieces.json',
      import.meta.url,
    ),
    'utf8',
  ),
) as {
  provenance: string
  pieces: Array<{
    food: string
    stage: string
    observation: { schema: string; owner_id: string; items: Array<{ meal: unknown }> }
  }>
}
describe('Actual SQL unit pieces flow through the exact owned DTO projector', () => {
  it('keeps literal originals, approximate audited corrections, proved Undo and legacy masses distinct', () => {
    const records = golden.pieces.map((piece) => {
      const raw = piece.observation,
        meals = raw.items.map((v) => v.meal)
      const units = readNutritionUnitsResult(raw, meals, raw.owner_id)
      const meal = projectNutritionMealFacts(meals, units, raw.owner_id)[0]
      expect(meal.id).toBe(raw.items[0].meal && (raw.items[0].meal as { id: string }).id)
      if (piece.food === 'legacy') expect(meal.display_quantity).toBeNull()
      else if (piece.stage === 'saved') {
        expect(meal.display_quantity).toMatchObject({
          estimated: true,
          provenance: 'audited_same_food_scale',
        })
        expect(meal.display_quantity?.reference.quantity_g).toBe(piece.food === 'milk' ? 206 : 30)
      } else {
        expect(meal.display_quantity).toMatchObject({
          value: piece.food === 'milk' ? 200 : 1,
          unit: piece.food === 'milk' ? 'mL' : 'scoop',
          estimated: false,
        })
      }
      return { food: piece.food, stage: piece.stage, meal }
    })
    expect(records).toHaveLength(7)
    if (process.env.NUTRITION_PROJECTED_UNIT_OUTPUT)
      writeFileSync(
        process.env.NUTRITION_PROJECTED_UNIT_OUTPUT,
        `${JSON.stringify({ provenance: 'Exact actual nutrition RPC pieces through actual public meal projector; no HTTP/day/Auth/clinical claim', sql_pieces_sha256: '140b2633e83046a0102d608237c2d0f1d6467e25bced17f0334e4d0b00dfd376', records }, null, 2)}\n`,
      )
  })
})
